contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetMinSum(_val1); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        bool firstOk = (afterFirst == _val1);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_val2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(firstOk && reverted && c.MinSum() == _val1 && afterFirst != before || before == afterFirst);
    }

    receive() external payable {}
}

